let gap = ONLINE_EVERY;
let buffed = {};
let stats = { jellybeansBuffed: 0, cropsPlanted: 0, jellybeansSpent: 0 };
let effectsByKind = {};

const cellKey = (r, c) => r + "," + c;
const onPlot = (r, c) => r >= 0 && r < 10 && c >= 0 && c < 10;

// Positive and negative effects a kind gives its neighbours.
function effectsOf(kind) {
  if (effectsByKind[kind] === undefined) {
    const i = info(kind);
    effectsByKind[kind] = i ? i.effects.concat(i.negativeEffects) : [];
  }
  return effectsByKind[kind];
}

// What the held effects add to the harvest multiplier.
function yieldBonus(effects) {
  const has = (e) => effects.includes(e);
  let v = has("improved_harvest_boost") ? 0.3 : has("harvest_boost") ? 0.2 : 0;
  if (has("harvest_loss") && !has("immunity")) v -= 0.2;
  return v;
}

function onSession() {
  if (lastSession !== null) gap = Math.max(1, cycle - lastSession);
  lastSession = cycle;
  if (!HARVEST_FULLY_GROWN) return;
  // Before the built-in phases, so the layout re-places the Jellybean this session.
  for (const p of plot.spawns(JELLY)) {
    if (p.fullyGrown && p.harvestable) p.harvest();
  }
}

function afterSession() {
  const ctx = context(gap);

  // Remove crops whose Jellybeans no longer need them.
  const kept = {};
  for (const k of keys(carriers)) {
    const cr = carriers[k];
    const here = plot.at(cr.row, cr.col);
    const alive = !!here && here.id === cr.plantId;
    cr.clients = cr.clients.filter((id) => ctx.want[id]);
    if (alive && cr.clients.length > 0) {
      kept[k] = cr;
      continue;
    }
    if (alive) here.break();
    restoreJellybean(cr, ctx);
  }
  carriers = kept;

  for (const j of ctx.targets) buffJellybean(j, ctx);

  metric("jellybeans buffed", stats.jellybeansBuffed);
  metric("buff crops planted", stats.cropsPlanted);
  metric("jellybeans spent on buffs", stats.jellybeansSpent);
}

// Which Jellybeans get harvested before the next session, plus the plot lookups the
// cell picking needs.
function context(look) {
  let stepEnding = false;
  for (const kind of STEP_ENDS_WHEN_DECAYS) {
    if (decaysWithin(kind, look)) stepEnding = true;
  }
  const targets = plot.spawns(JELLY).filter((p) =>
    !p.fullyGrown &&
    (p.stage + look >= p.readyStage || (stepEnding && p.stage + look >= 12)));

  const want = {}, targetAt = {}, slotCells = {}, layoutJelly = {};
  for (const j of targets) {
    want[j.id] = true;
    targetAt[cellKey(j.row, j.col)] = true;
  }
  const slots = plot.targets;
  for (const t of slots) {
    for (let dr = 0; dr < t.size; dr++)
      for (let dc = 0; dc < t.size; dc++) slotCells[cellKey(t.row + dr, t.col + dc)] = true;
  }
  for (const p of plot.layout.plants) {
    if (p.kind === JELLY) layoutJelly[cellKey(p.row, p.col)] = true;
  }
  return { targets, want, targetAt, slots, slotCells, layoutJelly, stepEnding };
}

// Will a plant of this kind decay before the next session? Its timer has to run out
// and its mutations be used up (mutated plants of one kind share that count), give or
// take MUTATIONS_SLACK.
function decaysWithin(kind, look) {
  const plants = plot.all(kind).filter((p) => !p.dead && p.decayCycles !== null);
  let pooled = 0;
  for (const p of plants) {
    if (p.timesMutated >= 1 && typeof p.mutatesRemaining === "number") pooled += p.mutatesRemaining;
  }
  return plants.some((p) => {
    if (p.decayCycles > look) return false;
    const left = p.mutatesRemaining;
    if (left === null) return true;
    if (typeof left !== "number") return false; // never decays
    return (p.timesMutated >= 1 ? pooled : left) <= MUTATIONS_SLACK;
  });
}

function buffJellybean(j, ctx) {
  const fixed = [];   // effects from neighbours that stay as they are
  const cells = [];   // cells a crop may go on
  const ours = [];    // our crops already next to it
  for (const [dr, dc] of DIRS) {
    const r = j.row + dr, c = j.col + dc;
    if (!onPlot(r, c)) continue;
    const n = plot.at(r, c);
    const free = !ctx.slotCells[cellKey(r, c)];
    if (!n) {
      if (free && USE_EMPTY_CELLS) cells.push({ r, c, n: null, cost: 0, now: [] });
      continue;
    }
    if (n.dead) continue;
    const own = carriers[cellKey(r, c)];
    if (own && own.plantId === n.id) ours.push(own);
    else if (free && n.kind === JELLY && n.placed) {
      cells.push({ r, c, n, cost: 1, now: effectsOf(n.kind) });
      continue;
    }
    for (const e of effectsOf(n.kind)) fixed.push(e);
  }

  // Try leaving each cell, Cocoa Beans or Nether Wart (3^cells ways, at most 81).
  const affordable = inventory.get(JELLY) - jellybeansOwed();
  let best = null;
  const ways = Math.pow(3, cells.length);
  for (let w = 0; w < ways; w++) {
    let m = w, effects = fixed.slice(), broken = 0, crops = 0, starved = 0, shared = 0, grown = 0;
    const pick = [];
    for (const cell of cells) {
      const choice = m % 3;
      m = Math.floor(m / 3);
      pick.push(choice);
      if (choice === 0) {
        for (const e of cell.now) effects.push(e);
        continue;
      }
      for (const e of effectsOf(CROPS[choice - 1])) effects.push(e);
      crops++;
      broken += cell.cost;
      // At a step end the spawners are cleared next session anyway.
      if (cell.cost && !ctx.stepEnding) starved += starvedSpawners(cell.r, cell.c, ctx);
      shared += neighbouringTargets(cell.r, cell.c, ctx);
      grown += grownSpawners(cell.r, cell.c, ctx);
    }
    if (broken > affordable) continue;
    const score = [-yieldBonus(effects), starved, broken, crops, -shared, -grown];
    if (!best || before(score, best.score)) best = { score, pick };
  }

  for (const own of ours) if (!own.clients.includes(j.id)) own.clients.push(j.id);
  if (!best || best.score[3] === 0) return;

  for (let i = 0; i < cells.length; i++) {
    if (best.pick[i] === 0) continue;
    const cell = cells[i];
    if (cell.n) cell.n.break();
    if (!plot.place(CROPS[best.pick[i] - 1], cell.r, cell.c)) {
      if (cell.n) plot.place(JELLY, cell.r, cell.c);
      continue;
    }
    const crop = plot.at(cell.r, cell.c);
    crop.waterIt(); // a dry crop gives no buffs
    carriers[cellKey(cell.r, cell.c)] = {
      row: cell.r, col: cell.c, plantId: crop.id, wasJelly: cell.cost === 1, clients: [j.id],
    };
    stats.cropsPlanted++;
  }
  if (!buffed[j.id]) {
    buffed[j.id] = true;
    stats.jellybeansBuffed++;
  }
}

function restoreJellybean(cr, ctx) {
  if (!cr.wasJelly || !ctx.layoutJelly[cellKey(cr.row, cr.col)]) return;
  if (!plot.isEmpty(cr.row, cr.col)) return;
  if (plot.place(JELLY, cr.row, cr.col)) stats.jellybeansSpent++;
}

function jellybeansOwed() {
  let n = 0;
  for (const k of keys(carriers)) if (carriers[k].wasJelly) n++;
  return n;
}

// Spawn targets around (r, c) that are still empty: breaking a Jellybean here takes
// away one of their requirements until it is put back.
function starvedSpawners(r, c, ctx) {
  return ctx.slots.filter((t) => !t.filled && inRing(t, r, c)).length;
}

// Targets around (r, c) that have already spawned (e.g. a growing Aloe).
function grownSpawners(r, c, ctx) {
  return ctx.slots.filter((t) => t.filled && inRing(t, r, c)).length;
}

// Other Jellybeans being buffed that a crop at (r, c) would also reach.
function neighbouringTargets(r, c, ctx) {
  let n = 0;
  for (const [dr, dc] of DIRS) if (ctx.targetAt[cellKey(r + dr, c + dc)]) n++;
  return n;
}

function inRing(t, r, c) {
  const inBlock = r >= t.row && r < t.row + t.size && c >= t.col && c < t.col + t.size;
  return !inBlock && r >= t.row - 1 && r <= t.row + t.size && c >= t.col - 1 && c <= t.col + t.size;
}

function before(a, b) {
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] < b[i];
  return false;
}
